insert into public.waypoints
  (id, trail_id, type, name, name_fil, note, latitude, longitude, elevation_m, position, distance_m)
values
  ('ulap-eco-trail-jump-off', 'ulap-eco-trail', 'jump_off', 'Ampucao jump-off', 'Jump-off sa Ampucao',
   'Register first at the Ampucao Barangay Hall, about 700 m east, then walk to the start of the trail.',
   16.3235585, 120.6491511, null, 1, 0),
  ('ulap-eco-trail-campsite-2', 'ulap-eco-trail', 'campsite', 'Camp Site 1', 'Camp Site 1',
   'Near Ambanaw-Paoay, the first peak. No water here; carry your own.',
   16.3066077, 120.6473494, null, 2, 2156),
  ('ulap-eco-trail-summit', 'ulap-eco-trail', 'summit', 'Mt. Ulap summit', 'Tuktok ng Mt. Ulap',
   'About 1,846 m. Camp Site 2, with a small store, is just below the summit on the way down to Sta. Fe.',
   16.2904204, 120.6311489, 1843, 3, 5086);

insert into public.reference_passages
  (id, destination_id, topic, language, text, source, sources, as_of)
values
  ('ulap-01-about-mt-ulap-en', 'ulap', 'getting_there', 'en',
   'Mt. Ulap is a Destination in Itogon, Benguet, south of Baguio. Its main Trail is the Mt. Ulap Eco-Trail, a traverse that starts in Barangay Ampucao and ends in Barangay Sta. Fe, crossing open pine and grass ridges with three main high points: Ambanaw-Paoay, Gungal Rock and the Mt. Ulap summit. The summit is about 1,846 m above sea level, the figure Pinoy Mountaineer calls official; other readings give 1,843 m to 1,856 m. There is no official difficulty rating; Pinoy Mountaineer rates it 3 out of 9, a beginner-friendly day hike. The traverse is roughly 8 to 9.5 km and takes about 4 to 6 hours.',
   'pinoymountaineer.com, openstreetmap.org, lakbaypinas.com',
   '[{"id": "U1", "title": "Mt. Ulap (1,846m) in Itogon, Benguet", "publisher": "Pinoy Mountaineer", "url": "https://www.pinoymountaineer.com/2015/11/mt-ulap-1846m-in-itogon-benguet.html"}, {"id": "U8", "title": "OpenStreetMap data (Mt. Ulap Eco Trail, Waypoints, hospitals)", "publisher": "OpenStreetMap contributors", "url": "https://www.openstreetmap.org/copyright"}, {"id": "U19", "title": "Ultimate Guide to Mt. Ulap in Itogon, Benguet", "publisher": "LakbayPinas", "url": "https://lakbaypinas.com/ultimate-guide-to-mt-ulap-in-itogon-benguet/"}]'::jsonb, '2026-10-10'),
  ('ulap-01-about-mt-ulap-fil', 'ulap', 'getting_there', 'fil',
   'Ang Mt. Ulap ay isang Destination sa Itogon, Benguet, sa timog ng Baguio. Ang pangunahing Trail nito ay ang Mt. Ulap Eco-Trail, isang traverse na nagsisimula sa Barangay Ampucao at nagtatapos sa Barangay Sta. Fe, dumadaan sa mga bukas na ridge na may pine at damo, at may tatlong pangunahing matataas na bahagi: Ambanaw-Paoay, Gungal Rock at ang summit ng Mt. Ulap. Mga 1,846 m above sea level ang summit, ang bilang na tinatawag ng Pinoy Mountaineer na opisyal; may ibang sukat na 1,843 m hanggang 1,856 m. Walang opisyal na difficulty rating; 3 sa 9 ito ayon sa Pinoy Mountaineer, isang day hike na pang-beginner. Mga 8 hanggang 9.5 km ang traverse at mga 4 hanggang 6 na oras.',
   'pinoymountaineer.com, openstreetmap.org, lakbaypinas.com',
   '[{"id": "U1", "title": "Mt. Ulap (1,846m) in Itogon, Benguet", "publisher": "Pinoy Mountaineer", "url": "https://www.pinoymountaineer.com/2015/11/mt-ulap-1846m-in-itogon-benguet.html"}, {"id": "U8", "title": "OpenStreetMap data (Mt. Ulap Eco Trail, Waypoints, hospitals)", "publisher": "OpenStreetMap contributors", "url": "https://www.openstreetmap.org/copyright"}, {"id": "U19", "title": "Ultimate Guide to Mt. Ulap in Itogon, Benguet", "publisher": "LakbayPinas", "url": "https://lakbaypinas.com/ultimate-guide-to-mt-ulap-in-itogon-benguet/"}]'::jsonb, '2026-10-10'),
  ('ulap-02-getting-to-the-ampucao-jump-off-en', 'ulap', 'getting_there', 'en',
   'The Mt. Ulap Eco-Trail starts in Barangay Ampucao, Itogon, Benguet, off the road toward Philex. Hikers register at the Ampucao Barangay Hall and park near Ampucao Elementary School, which was also the registration point in 2020. Parking has cost about ₱100 per vehicle. The usual direction is Ampucao to Sta. Fe, so arrange your ride home from Sta. Fe, the exit barangay, before you start. One blog places the jump-off at the Itogon barangay hall; that is a mistake, as every other source says Ampucao.',
   'pinoymountaineer.com, openstreetmap.org, transitpinas.com, awanderfulsole.com, lakbaypinas.com',
   '[{"id": "U1", "title": "Mt. Ulap (1,846m) in Itogon, Benguet", "publisher": "Pinoy Mountaineer", "url": "https://www.pinoymountaineer.com/2015/11/mt-ulap-1846m-in-itogon-benguet.html"}, {"id": "U8", "title": "OpenStreetMap data (Mt. Ulap Eco Trail, Waypoints, hospitals)", "publisher": "OpenStreetMap contributors", "url": "https://www.openstreetmap.org/copyright"}, {"id": "U15", "title": "Mt. Ulap and Gungal Rock (Benguet)", "publisher": "Transit Pinas", "url": "https://transitpinas.com/benguet-mt-ulap-gungal/"}, {"id": "U16", "title": "Mt. Ulap day hike guide (Ampucao–Sta. Fe traverse)", "publisher": "A Wanderful Sole", "url": "https://www.awanderfulsole.com/mt-ulap-dayhike-guide-ampucao-sta-fee-traverse/"}, {"id": "U19", "title": "Ultimate Guide to Mt. Ulap in Itogon, Benguet", "publisher": "LakbayPinas", "url": "https://lakbaypinas.com/ultimate-guide-to-mt-ulap-in-itogon-benguet/"}]'::jsonb, '2026-10-10'),
  ('ulap-02-getting-to-the-ampucao-jump-off-fil', 'ulap', 'getting_there', 'fil',
   'Nagsisimula ang Mt. Ulap Eco-Trail sa Barangay Ampucao, Itogon, Benguet, sa gilid ng kalsadang papuntang Philex. Nagre-register ang mga hiker sa Ampucao Barangay Hall at pumaparada malapit sa Ampucao Elementary School, na siya ring registration point noong 2020. Mga ₱100 bawat sasakyan ang parking. Karaniwang direksyon ay Ampucao papuntang Sta. Fe, kaya ayusin na ang sasakyan pauwi mula Sta. Fe, ang exit na barangay, bago magsimula. May isang blog na nagsasabing nasa Itogon barangay hall ang jump-off; mali iyon, dahil Ampucao ang sinasabi ng lahat ng ibang sources.',
   'pinoymountaineer.com, openstreetmap.org, transitpinas.com, awanderfulsole.com, lakbaypinas.com',
   '[{"id": "U1", "title": "Mt. Ulap (1,846m) in Itogon, Benguet", "publisher": "Pinoy Mountaineer", "url": "https://www.pinoymountaineer.com/2015/11/mt-ulap-1846m-in-itogon-benguet.html"}, {"id": "U8", "title": "OpenStreetMap data (Mt. Ulap Eco Trail, Waypoints, hospitals)", "publisher": "OpenStreetMap contributors", "url": "https://www.openstreetmap.org/copyright"}, {"id": "U15", "title": "Mt. Ulap and Gungal Rock (Benguet)", "publisher": "Transit Pinas", "url": "https://transitpinas.com/benguet-mt-ulap-gungal/"}, {"id": "U16", "title": "Mt. Ulap day hike guide (Ampucao–Sta. Fe traverse)", "publisher": "A Wanderful Sole", "url": "https://www.awanderfulsole.com/mt-ulap-dayhike-guide-ampucao-sta-fee-traverse/"}, {"id": "U19", "title": "Ultimate Guide to Mt. Ulap in Itogon, Benguet", "publisher": "LakbayPinas", "url": "https://lakbaypinas.com/ultimate-guide-to-mt-ulap-in-itogon-benguet/"}]'::jsonb, '2026-10-10'),
  ('ulap-03-registration-and-hours-en', 'ulap', 'registration', 'en',
   'On the Mt. Ulap Eco-Trail, every group registers at the Ampucao Barangay Hall before starting. Hikers sign a manifest with emergency contacts, pay their fees, and get a short orientation. Opening hours differ between sources. In 2022, day hikers could register from 5 AM until noon, and overnight hikers from 9 AM until 2 PM, with reservations through an online form. A 2026 blog says registration opens at 4 AM on weekends and 5 AM on weekdays, that small groups can walk in, and does not mention a cut-off. Register early to finish in daylight, and confirm the current hours with the barangay or the Itogon tourism office.',
   'transitpinas.com, awanderfulsole.com, syramay.com, lakbaypinas.com',
   '[{"id": "U15", "title": "Mt. Ulap and Gungal Rock (Benguet)", "publisher": "Transit Pinas", "url": "https://transitpinas.com/benguet-mt-ulap-gungal/"}, {"id": "U16", "title": "Mt. Ulap day hike guide (Ampucao–Sta. Fe traverse)", "publisher": "A Wanderful Sole", "url": "https://www.awanderfulsole.com/mt-ulap-dayhike-guide-ampucao-sta-fee-traverse/"}, {"id": "U18", "title": "Mt. Ulap traverse day hike guide", "publisher": "syramay.com", "url": "https://www.syramay.com/mt-ulap-traverse-dayhike-guide-itinerary/"}, {"id": "U19", "title": "Ultimate Guide to Mt. Ulap in Itogon, Benguet", "publisher": "LakbayPinas", "url": "https://lakbaypinas.com/ultimate-guide-to-mt-ulap-in-itogon-benguet/"}]'::jsonb, '2026-10-10'),
  ('ulap-03-registration-and-hours-fil', 'ulap', 'registration', 'fil',
   'Sa Mt. Ulap Eco-Trail, nagre-register muna ang bawat grupo sa Ampucao Barangay Hall bago magsimula. Pumipirma ang mga hiker sa isang manifest na may emergency contacts, nagbabayad ng fees, at may maikling orientation. Magkakaiba ang oras ayon sa sources. Noong 2022, puwedeng mag-register ang mga day hiker mula 5 AM hanggang tanghali, at ang overnight mula 9 AM hanggang 2 PM, na may reservation sa isang online form. Ayon sa isang 2026 blog, nagbubukas ang registration nang 4 AM tuwing weekend at 5 AM tuwing weekday, puwedeng mag-walk in ang maliliit na grupo, at walang binanggit na cut-off. Mag-register nang maaga para matapos habang maliwanag, at i-confirm ang oras sa barangay o sa Itogon tourism office.',
   'transitpinas.com, awanderfulsole.com, syramay.com, lakbaypinas.com',
   '[{"id": "U15", "title": "Mt. Ulap and Gungal Rock (Benguet)", "publisher": "Transit Pinas", "url": "https://transitpinas.com/benguet-mt-ulap-gungal/"}, {"id": "U16", "title": "Mt. Ulap day hike guide (Ampucao–Sta. Fe traverse)", "publisher": "A Wanderful Sole", "url": "https://www.awanderfulsole.com/mt-ulap-dayhike-guide-ampucao-sta-fee-traverse/"}, {"id": "U18", "title": "Mt. Ulap traverse day hike guide", "publisher": "syramay.com", "url": "https://www.syramay.com/mt-ulap-traverse-dayhike-guide-itinerary/"}, {"id": "U19", "title": "Ultimate Guide to Mt. Ulap in Itogon, Benguet", "publisher": "LakbayPinas", "url": "https://lakbaypinas.com/ultimate-guide-to-mt-ulap-in-itogon-benguet/"}]'::jsonb, '2026-10-10'),
  ('ulap-04-fees-en', 'ulap', 'registration', 'en',
   'No official fee list for the Mt. Ulap Eco-Trail was found, so these figures come from hikers'' reports and may have changed. Recent reports (2022 to 2026) give a registration fee of about ₱100 per person and a DENR environmental fee of about ₱30 per adult (₱15 for students and ₱100 for foreigners in a January 2025 report). Guides are a separate cost per group. Camping fees differ between sources, from about ₱200 per group to ₱800 per site plus a per-person fee. Parking is about ₱100 per vehicle and a shower about ₱40 to ₱50. Bring cash in small bills and confirm the amounts at the Ampucao Barangay Hall.',
   'transitpinas.com, awanderfulsole.com, lakbaypinas.com, joansfootprints.com',
   '[{"id": "U15", "title": "Mt. Ulap and Gungal Rock (Benguet)", "publisher": "Transit Pinas", "url": "https://transitpinas.com/benguet-mt-ulap-gungal/"}, {"id": "U16", "title": "Mt. Ulap day hike guide (Ampucao–Sta. Fe traverse)", "publisher": "A Wanderful Sole", "url": "https://www.awanderfulsole.com/mt-ulap-dayhike-guide-ampucao-sta-fee-traverse/"}, {"id": "U19", "title": "Ultimate Guide to Mt. Ulap in Itogon, Benguet", "publisher": "LakbayPinas", "url": "https://lakbaypinas.com/ultimate-guide-to-mt-ulap-in-itogon-benguet/"}, {"id": "U20", "title": "DIY travel guide to Mt. Ulap in Benguet", "publisher": "Joan''s Footprints", "url": "https://joansfootprints.com/2026/06/17/2020-diy-travel-guide-to-mt-ulap-in-benguet-itinerary-budget/"}]'::jsonb, '2026-10-10'),
  ('ulap-04-fees-fil', 'ulap', 'registration', 'fil',
   'Walang nakitang opisyal na listahan ng fees para sa Mt. Ulap Eco-Trail, kaya galing sa mga ulat ng hiker ang mga bilang na ito at puwedeng nagbago na. Ayon sa mga bagong ulat (2022 hanggang 2026), mga ₱100 bawat tao ang registration fee at mga ₱30 bawat adult ang DENR environmental fee (₱15 sa estudyante at ₱100 sa foreigner ayon sa isang ulat noong Enero 2025). Hiwalay na bayad bawat grupo ang guide. Magkakaiba ang camping fee ayon sa sources, mula mga ₱200 bawat grupo hanggang ₱800 bawat site at may dagdag pang bayad bawat tao. Mga ₱100 bawat sasakyan ang parking at mga ₱40 hanggang ₱50 ang shower. Magdala ng cash na barya-barya at i-confirm ang halaga sa Ampucao Barangay Hall.',
   'transitpinas.com, awanderfulsole.com, lakbaypinas.com, joansfootprints.com',
   '[{"id": "U15", "title": "Mt. Ulap and Gungal Rock (Benguet)", "publisher": "Transit Pinas", "url": "https://transitpinas.com/benguet-mt-ulap-gungal/"}, {"id": "U16", "title": "Mt. Ulap day hike guide (Ampucao–Sta. Fe traverse)", "publisher": "A Wanderful Sole", "url": "https://www.awanderfulsole.com/mt-ulap-dayhike-guide-ampucao-sta-fee-traverse/"}, {"id": "U19", "title": "Ultimate Guide to Mt. Ulap in Itogon, Benguet", "publisher": "LakbayPinas", "url": "https://lakbaypinas.com/ultimate-guide-to-mt-ulap-in-itogon-benguet/"}, {"id": "U20", "title": "DIY travel guide to Mt. Ulap in Benguet", "publisher": "Joan''s Footprints", "url": "https://joansfootprints.com/2026/06/17/2020-diy-travel-guide-to-mt-ulap-in-benguet-itinerary-budget/"}]'::jsonb, '2026-10-10'),
  ('ulap-05-guides-and-porters-en', 'ulap', 'registration', 'en',
   'A local guide is mandatory on the Mt. Ulap Eco-Trail. One guide takes a group of up to 7 hikers, assigned at registration in Ampucao. Reported rates for 2025 to 2026 are about ₱800 per group for a day hike and ₱1,600 for an overnight hike, up from about ₱600 and ₱1,000 in 2020 to 2022. Porters have been available for about ₱800 one way or ₱1,200 both ways, carrying up to 15 kg. These rates come from hikers'' reports, not an official list, so confirm them at the Ampucao Barangay Hall.',
   'transitpinas.com, awanderfulsole.com, lakbaypinas.com, joansfootprints.com',
   '[{"id": "U15", "title": "Mt. Ulap and Gungal Rock (Benguet)", "publisher": "Transit Pinas", "url": "https://transitpinas.com/benguet-mt-ulap-gungal/"}, {"id": "U16", "title": "Mt. Ulap day hike guide (Ampucao–Sta. Fe traverse)", "publisher": "A Wanderful Sole", "url": "https://www.awanderfulsole.com/mt-ulap-dayhike-guide-ampucao-sta-fee-traverse/"}, {"id": "U19", "title": "Ultimate Guide to Mt. Ulap in Itogon, Benguet", "publisher": "LakbayPinas", "url": "https://lakbaypinas.com/ultimate-guide-to-mt-ulap-in-itogon-benguet/"}, {"id": "U20", "title": "DIY travel guide to Mt. Ulap in Benguet", "publisher": "Joan''s Footprints", "url": "https://joansfootprints.com/2026/06/17/2020-diy-travel-guide-to-mt-ulap-in-benguet-itinerary-budget/"}]'::jsonb, '2026-10-10'),
  ('ulap-05-guides-and-porters-fil', 'ulap', 'registration', 'fil',
   'Mandatory ang local guide sa Mt. Ulap Eco-Trail. Isang guide para sa grupo na hanggang 7 hiker, na ina-assign sa registration sa Ampucao. Ayon sa mga ulat para sa 2025 hanggang 2026, mga ₱800 bawat grupo ang guide sa day hike at ₱1,600 sa overnight, mula sa mga ₱600 at ₱1,000 noong 2020 hanggang 2022. May mga porter na mga ₱800 one way o ₱1,200 balikan, hanggang 15 kg ang dala. Galing sa ulat ng mga hiker ang mga rate na ito, hindi sa opisyal na listahan, kaya i-confirm sa Ampucao Barangay Hall.',
   'transitpinas.com, awanderfulsole.com, lakbaypinas.com, joansfootprints.com',
   '[{"id": "U15", "title": "Mt. Ulap and Gungal Rock (Benguet)", "publisher": "Transit Pinas", "url": "https://transitpinas.com/benguet-mt-ulap-gungal/"}, {"id": "U16", "title": "Mt. Ulap day hike guide (Ampucao–Sta. Fe traverse)", "publisher": "A Wanderful Sole", "url": "https://www.awanderfulsole.com/mt-ulap-dayhike-guide-ampucao-sta-fee-traverse/"}, {"id": "U19", "title": "Ultimate Guide to Mt. Ulap in Itogon, Benguet", "publisher": "LakbayPinas", "url": "https://lakbaypinas.com/ultimate-guide-to-mt-ulap-in-itogon-benguet/"}, {"id": "U20", "title": "DIY travel guide to Mt. Ulap in Benguet", "publisher": "Joan''s Footprints", "url": "https://joansfootprints.com/2026/06/17/2020-diy-travel-guide-to-mt-ulap-in-benguet-itinerary-budget/"}]'::jsonb, '2026-10-10'),
  ('ulap-06-the-traverse-at-a-glance-en', 'ulap', 'getting_there', 'en',
   'The Mt. Ulap Eco-Trail runs from Ampucao to Sta. Fe. In order, the Waypoints are: the Ampucao jump-off, Ambanaw-Paoay (the first peak), Gungal Rock (the second), Campsite 2 with a small store, the Mt. Ulap summit (the third peak, about 1,846 m), the Pong-ol burial caves, and the Sta. Fe exit. Sources put the length at about 8 km to 9.4 km, with roughly 400 m of climbing. Typical times: about 1 hour to Ambanaw-Paoay, 1 hour more to Gungal, 20 minutes to the summit, and about 1.5 hours down to Sta. Fe, for 4 to 6 hours in total. Some groups go the reverse way, from Sta. Fe.',
   'pinoymountaineer.com, openstreetmap.org, transitpinas.com, lakbaypinas.com, joansfootprints.com',
   '[{"id": "U1", "title": "Mt. Ulap (1,846m) in Itogon, Benguet", "publisher": "Pinoy Mountaineer", "url": "https://www.pinoymountaineer.com/2015/11/mt-ulap-1846m-in-itogon-benguet.html"}, {"id": "U8", "title": "OpenStreetMap data (Mt. Ulap Eco Trail, Waypoints, hospitals)", "publisher": "OpenStreetMap contributors", "url": "https://www.openstreetmap.org/copyright"}, {"id": "U15", "title": "Mt. Ulap and Gungal Rock (Benguet)", "publisher": "Transit Pinas", "url": "https://transitpinas.com/benguet-mt-ulap-gungal/"}, {"id": "U19", "title": "Ultimate Guide to Mt. Ulap in Itogon, Benguet", "publisher": "LakbayPinas", "url": "https://lakbaypinas.com/ultimate-guide-to-mt-ulap-in-itogon-benguet/"}, {"id": "U20", "title": "DIY travel guide to Mt. Ulap in Benguet", "publisher": "Joan''s Footprints", "url": "https://joansfootprints.com/2026/06/17/2020-diy-travel-guide-to-mt-ulap-in-benguet-itinerary-budget/"}]'::jsonb, '2026-10-10'),
  ('ulap-06-the-traverse-at-a-glance-fil', 'ulap', 'getting_there', 'fil',
   'Mula Ampucao hanggang Sta. Fe ang Mt. Ulap Eco-Trail. Sunod-sunod, ang mga Waypoint ay: ang jump-off sa Ampucao, Ambanaw-Paoay (unang peak), Gungal Rock (pangalawa), Campsite 2 na may maliit na tindahan, ang summit ng Mt. Ulap (pangatlong peak, mga 1,846 m), ang Pong-ol burial caves, at ang exit sa Sta. Fe. Ayon sa sources, mga 8 km hanggang 9.4 km ang haba, na may mga 400 m na akyatin. Karaniwang oras: mga 1 oras papuntang Ambanaw-Paoay, 1 oras pa papuntang Gungal, 20 minuto papuntang summit, at mga 1.5 oras pababa sa Sta. Fe, kabuuang 4 hanggang 6 na oras. May mga grupong bumabaliktad, mula Sta. Fe.',
   'pinoymountaineer.com, openstreetmap.org, transitpinas.com, lakbaypinas.com, joansfootprints.com',
   '[{"id": "U1", "title": "Mt. Ulap (1,846m) in Itogon, Benguet", "publisher": "Pinoy Mountaineer", "url": "https://www.pinoymountaineer.com/2015/11/mt-ulap-1846m-in-itogon-benguet.html"}, {"id": "U8", "title": "OpenStreetMap data (Mt. Ulap Eco Trail, Waypoints, hospitals)", "publisher": "OpenStreetMap contributors", "url": "https://www.openstreetmap.org/copyright"}, {"id": "U15", "title": "Mt. Ulap and Gungal Rock (Benguet)", "publisher": "Transit Pinas", "url": "https://transitpinas.com/benguet-mt-ulap-gungal/"}, {"id": "U19", "title": "Ultimate Guide to Mt. Ulap in Itogon, Benguet", "publisher": "LakbayPinas", "url": "https://lakbaypinas.com/ultimate-guide-to-mt-ulap-in-itogon-benguet/"}, {"id": "U20", "title": "DIY travel guide to Mt. Ulap in Benguet", "publisher": "Joan''s Footprints", "url": "https://joansfootprints.com/2026/06/17/2020-diy-travel-guide-to-mt-ulap-in-benguet-itinerary-budget/"}]'::jsonb, '2026-10-10'),
  ('ulap-07-ampucao-to-ambanaw-paoay-and-gungal-en', 'ulap', 'getting_there', 'en',
   'The first part of the Mt. Ulap Eco-Trail climbs from the Ampucao jump-off (about 1,440 to 1,500 m) through pine forest and grassland to Ambanaw-Paoay, the first peak, at about 1,788 m. This takes about an hour and is roughly 3.6 km in, by one blog''s count. Camp Site 1 is near Ambanaw-Paoay. From there the Trail follows the ridge for about another hour to Gungal Rock, the second peak, at about 1,800 m and about 5 km from the start. There are toilets near Gungal. The Mt. Ulap summit is about 20 minutes beyond Gungal. The ridges are open, so expect sun and wind on this stretch.',
   'openstreetmap.org, transitpinas.com, lakbaypinas.com, joansfootprints.com',
   '[{"id": "U8", "title": "OpenStreetMap data (Mt. Ulap Eco Trail, Waypoints, hospitals)", "publisher": "OpenStreetMap contributors", "url": "https://www.openstreetmap.org/copyright"}, {"id": "U15", "title": "Mt. Ulap and Gungal Rock (Benguet)", "publisher": "Transit Pinas", "url": "https://transitpinas.com/benguet-mt-ulap-gungal/"}, {"id": "U19", "title": "Ultimate Guide to Mt. Ulap in Itogon, Benguet", "publisher": "LakbayPinas", "url": "https://lakbaypinas.com/ultimate-guide-to-mt-ulap-in-itogon-benguet/"}, {"id": "U20", "title": "DIY travel guide to Mt. Ulap in Benguet", "publisher": "Joan''s Footprints", "url": "https://joansfootprints.com/2026/06/17/2020-diy-travel-guide-to-mt-ulap-in-benguet-itinerary-budget/"}]'::jsonb, '2026-10-10'),
  ('ulap-07-ampucao-to-ambanaw-paoay-and-gungal-fil', 'ulap', 'getting_there', 'fil',
   'Ang unang bahagi ng Mt. Ulap Eco-Trail ay umaakyat mula sa jump-off sa Ampucao (mga 1,440 hanggang 1,500 m) dumadaan sa pine forest at damuhan papuntang Ambanaw-Paoay, ang unang peak, sa mga 1,788 m. Mga isang oras ito at mga 3.6 km mula simula, ayon sa isang blog. Malapit sa Ambanaw-Paoay ang Camp Site 1. Mula roon, sinusundan ng Trail ang ridge nang mga isang oras pa papuntang Gungal Rock, ang pangalawang peak, sa mga 1,800 m at mga 5 km mula simula. May mga toilet malapit sa Gungal. Mga 20 minuto pa mula Gungal ang summit ng Mt. Ulap. Bukas ang mga ridge, kaya asahan ang araw at hangin sa bahaging ito.',
   'openstreetmap.org, transitpinas.com, lakbaypinas.com, joansfootprints.com',
   '[{"id": "U8", "title": "OpenStreetMap data (Mt. Ulap Eco Trail, Waypoints, hospitals)", "publisher": "OpenStreetMap contributors", "url": "https://www.openstreetmap.org/copyright"}, {"id": "U15", "title": "Mt. Ulap and Gungal Rock (Benguet)", "publisher": "Transit Pinas", "url": "https://transitpinas.com/benguet-mt-ulap-gungal/"}, {"id": "U19", "title": "Ultimate Guide to Mt. Ulap in Itogon, Benguet", "publisher": "LakbayPinas", "url": "https://lakbaypinas.com/ultimate-guide-to-mt-ulap-in-itogon-benguet/"}, {"id": "U20", "title": "DIY travel guide to Mt. Ulap in Benguet", "publisher": "Joan''s Footprints", "url": "https://joansfootprints.com/2026/06/17/2020-diy-travel-guide-to-mt-ulap-in-benguet-itinerary-budget/"}]'::jsonb, '2026-10-10'),
  ('ulap-08-gungal-rock-safety-en', 'ulap', 'hazards', 'en',
   'Gungal Rock is the most famous photo spot on the Mt. Ulap Eco-Trail, and the most dangerous. It is a slanted rock that ends in a cliff drop. Pinoy Mountaineer warns that a careless photo there could be fatal, and rangers limit each person''s time on the rock to a few seconds, especially when there is a queue on weekends. Keep your turn short, stay back from the drop, and follow the guide''s and rangers'' instructions. If someone falls or is injured, call for help and open the Sprains and fractures or Bleeding wounds Emergency Guide.',
   'pinoymountaineer.com, thequeensescape.com, syramay.com',
   '[{"id": "U1", "title": "Mt. Ulap (1,846m) in Itogon, Benguet", "publisher": "Pinoy Mountaineer", "url": "https://www.pinoymountaineer.com/2015/11/mt-ulap-1846m-in-itogon-benguet.html"}, {"id": "U17", "title": "Mt. Ulap Eco-Trail, Itogon, Benguet travel guide", "publisher": "The Queen''s Escape", "url": "https://thequeensescape.com/mt-ulap-eco-trail-itogon-benguet-2020-travel-guide/"}, {"id": "U18", "title": "Mt. Ulap traverse day hike guide", "publisher": "syramay.com", "url": "https://www.syramay.com/mt-ulap-traverse-dayhike-guide-itinerary/"}]'::jsonb, '2026-10-10'),
  ('ulap-08-gungal-rock-safety-fil', 'ulap', 'hazards', 'fil',
   'Ang Gungal Rock ang pinakasikat na photo spot sa Mt. Ulap Eco-Trail, at ang pinakadelikado. Isa itong pahilig na bato na nagtatapos sa bangin. Nagbabala ang Pinoy Mountaineer na puwedeng ikamatay ang pabayang pagpapa-picture doon, at nililimitahan ng mga ranger sa ilang segundo lang ang bawat tao sa bato, lalo na kapag mahaba ang pila tuwing weekend. Bilisan ang turn mo, lumayo sa bangin, at sundin ang guide at mga ranger. Kung may nahulog o nasaktan, humingi ng tulong at buksan ang Emergency Guide na Sprains and fractures o Bleeding wounds.',
   'pinoymountaineer.com, thequeensescape.com, syramay.com',
   '[{"id": "U1", "title": "Mt. Ulap (1,846m) in Itogon, Benguet", "publisher": "Pinoy Mountaineer", "url": "https://www.pinoymountaineer.com/2015/11/mt-ulap-1846m-in-itogon-benguet.html"}, {"id": "U17", "title": "Mt. Ulap Eco-Trail, Itogon, Benguet travel guide", "publisher": "The Queen''s Escape", "url": "https://thequeensescape.com/mt-ulap-eco-trail-itogon-benguet-2020-travel-guide/"}, {"id": "U18", "title": "Mt. Ulap traverse day hike guide", "publisher": "syramay.com", "url": "https://www.syramay.com/mt-ulap-traverse-dayhike-guide-itinerary/"}]'::jsonb, '2026-10-10'),
  ('ulap-09-summit-and-campsites-en', 'ulap', 'campsites', 'en',
   'The Mt. Ulap summit, the third peak of the Eco-Trail at about 1,846 m, is about 20 minutes past Gungal Rock. OpenStreetMap shows two marked campsites: Camp Site 1 near Ambanaw-Paoay and Camp Site 2 just below the summit, where a small store has sold food and water. Overnight hikes are allowed with an overnight guide rate. One 2022 plan backtracked from Campsite 2 to Gungal for sunrise, then went over the summit and down to Sta. Fe. Camping fees differ by source, from about ₱200 per group to ₱800 per site plus extra per person, so confirm them at registration. Camp only at the marked campsites.',
   'openstreetmap.org, transitpinas.com, lakbaypinas.com, joansfootprints.com',
   '[{"id": "U8", "title": "OpenStreetMap data (Mt. Ulap Eco Trail, Waypoints, hospitals)", "publisher": "OpenStreetMap contributors", "url": "https://www.openstreetmap.org/copyright"}, {"id": "U15", "title": "Mt. Ulap and Gungal Rock (Benguet)", "publisher": "Transit Pinas", "url": "https://transitpinas.com/benguet-mt-ulap-gungal/"}, {"id": "U19", "title": "Ultimate Guide to Mt. Ulap in Itogon, Benguet", "publisher": "LakbayPinas", "url": "https://lakbaypinas.com/ultimate-guide-to-mt-ulap-in-itogon-benguet/"}, {"id": "U20", "title": "DIY travel guide to Mt. Ulap in Benguet", "publisher": "Joan''s Footprints", "url": "https://joansfootprints.com/2026/06/17/2020-diy-travel-guide-to-mt-ulap-in-benguet-itinerary-budget/"}]'::jsonb, '2026-10-10'),
  ('ulap-09-summit-and-campsites-fil', 'ulap', 'campsites', 'fil',
   'Ang summit ng Mt. Ulap, ang pangatlong peak ng Eco-Trail sa mga 1,846 m, ay mga 20 minuto lampas sa Gungal Rock. Sa OpenStreetMap, may dalawang markadong campsite: Camp Site 1 malapit sa Ambanaw-Paoay at Camp Site 2 sa ibaba lang ng summit, kung saan may maliit na tindahang nagbebenta ng pagkain at tubig. Puwede ang overnight hike, na may overnight na rate ng guide. Sa isang plano noong 2022, bumalik sila mula Campsite 2 papuntang Gungal para sa sunrise, tapos dumaan sa summit at bumaba sa Sta. Fe. Magkakaiba ang camping fee ayon sa sources, mula mga ₱200 bawat grupo hanggang ₱800 bawat site at may dagdag bawat tao, kaya i-confirm sa registration. Sa mga markadong campsite lang mag-camp.',
   'openstreetmap.org, transitpinas.com, lakbaypinas.com, joansfootprints.com',
   '[{"id": "U8", "title": "OpenStreetMap data (Mt. Ulap Eco Trail, Waypoints, hospitals)", "publisher": "OpenStreetMap contributors", "url": "https://www.openstreetmap.org/copyright"}, {"id": "U15", "title": "Mt. Ulap and Gungal Rock (Benguet)", "publisher": "Transit Pinas", "url": "https://transitpinas.com/benguet-mt-ulap-gungal/"}, {"id": "U19", "title": "Ultimate Guide to Mt. Ulap in Itogon, Benguet", "publisher": "LakbayPinas", "url": "https://lakbaypinas.com/ultimate-guide-to-mt-ulap-in-itogon-benguet/"}, {"id": "U20", "title": "DIY travel guide to Mt. Ulap in Benguet", "publisher": "Joan''s Footprints", "url": "https://joansfootprints.com/2026/06/17/2020-diy-travel-guide-to-mt-ulap-in-benguet-itinerary-budget/"}]'::jsonb, '2026-10-10'),
  ('ulap-10-descent-to-pong-ol-and-sta-fe-en', 'ulap', 'getting_there', 'en',
   'From the Mt. Ulap summit, the Eco-Trail descends steeply on loose ground to the Pong-ol burial caves, then continues down to Barangay Sta. Fe, the exit, at about 1,280 m. Several hikers describe this as the hardest part of the traverse, and it is slippery when wet. The descent takes about 1.5 hours. Near Sta. Fe the path becomes cemented and crosses hanging bridges. The Pong-ol caves hold burial remains and are a cultural site: look from a distance and do not touch anything. If you twist an ankle or get blisters on the way down, open the Sprains and fractures or Blisters Guide.',
   'pinoymountaineer.com, openstreetmap.org, transitpinas.com, awanderfulsole.com, lakbaypinas.com',
   '[{"id": "U1", "title": "Mt. Ulap (1,846m) in Itogon, Benguet", "publisher": "Pinoy Mountaineer", "url": "https://www.pinoymountaineer.com/2015/11/mt-ulap-1846m-in-itogon-benguet.html"}, {"id": "U8", "title": "OpenStreetMap data (Mt. Ulap Eco Trail, Waypoints, hospitals)", "publisher": "OpenStreetMap contributors", "url": "https://www.openstreetmap.org/copyright"}, {"id": "U15", "title": "Mt. Ulap and Gungal Rock (Benguet)", "publisher": "Transit Pinas", "url": "https://transitpinas.com/benguet-mt-ulap-gungal/"}, {"id": "U16", "title": "Mt. Ulap day hike guide (Ampucao–Sta. Fe traverse)", "publisher": "A Wanderful Sole", "url": "https://www.awanderfulsole.com/mt-ulap-dayhike-guide-ampucao-sta-fee-traverse/"}, {"id": "U19", "title": "Ultimate Guide to Mt. Ulap in Itogon, Benguet", "publisher": "LakbayPinas", "url": "https://lakbaypinas.com/ultimate-guide-to-mt-ulap-in-itogon-benguet/"}]'::jsonb, '2026-10-10'),
  ('ulap-10-descent-to-pong-ol-and-sta-fe-fil', 'ulap', 'getting_there', 'fil',
   'Mula sa summit ng Mt. Ulap, matarik at madulas ang lupa pababa ng Eco-Trail papuntang Pong-ol burial caves, tapos tuloy-tuloy pababa sa Barangay Sta. Fe, ang exit, sa mga 1,280 m. Ayon sa ilang hiker, ito ang pinakamahirap na bahagi ng traverse, at madulas kapag basa. Mga 1.5 oras ang pagbaba. Malapit sa Sta. Fe, sementado na ang daan at may mga hanging bridge. May mga labi ng patay sa Pong-ol caves at isa itong cultural site: tumingin mula sa malayo at huwag galawin ang kahit ano. Kung napilay ka o nagka-paltos pababa, buksan ang Guide na Sprains and fractures o Blisters.',
   'pinoymountaineer.com, openstreetmap.org, transitpinas.com, awanderfulsole.com, lakbaypinas.com',
   '[{"id": "U1", "title": "Mt. Ulap (1,846m) in Itogon, Benguet", "publisher": "Pinoy Mountaineer", "url": "https://www.pinoymountaineer.com/2015/11/mt-ulap-1846m-in-itogon-benguet.html"}, {"id": "U8", "title": "OpenStreetMap data (Mt. Ulap Eco Trail, Waypoints, hospitals)", "publisher": "OpenStreetMap contributors", "url": "https://www.openstreetmap.org/copyright"}, {"id": "U15", "title": "Mt. Ulap and Gungal Rock (Benguet)", "publisher": "Transit Pinas", "url": "https://transitpinas.com/benguet-mt-ulap-gungal/"}, {"id": "U16", "title": "Mt. Ulap day hike guide (Ampucao–Sta. Fe traverse)", "publisher": "A Wanderful Sole", "url": "https://www.awanderfulsole.com/mt-ulap-dayhike-guide-ampucao-sta-fee-traverse/"}, {"id": "U19", "title": "Ultimate Guide to Mt. Ulap in Itogon, Benguet", "publisher": "LakbayPinas", "url": "https://lakbaypinas.com/ultimate-guide-to-mt-ulap-in-itogon-benguet/"}]'::jsonb, '2026-10-10'),
  ('ulap-11-water-en', 'ulap', 'water', 'en',
   'There is no reliable natural water source on the Mt. Ulap Eco-Trail, and none at the campsites. The only water on the way has been sold at the small store at Campsite 2 near the summit, which may be closed or sold out. Bring at least 2 litres per person from Ampucao; the ridges have little shade. If someone shows signs of dehydration, open the Dehydration Emergency Guide.',
   'transitpinas.com, thequeensescape.com, lakbaypinas.com',
   '[{"id": "U15", "title": "Mt. Ulap and Gungal Rock (Benguet)", "publisher": "Transit Pinas", "url": "https://transitpinas.com/benguet-mt-ulap-gungal/"}, {"id": "U17", "title": "Mt. Ulap Eco-Trail, Itogon, Benguet travel guide", "publisher": "The Queen''s Escape", "url": "https://thequeensescape.com/mt-ulap-eco-trail-itogon-benguet-2020-travel-guide/"}, {"id": "U19", "title": "Ultimate Guide to Mt. Ulap in Itogon, Benguet", "publisher": "LakbayPinas", "url": "https://lakbaypinas.com/ultimate-guide-to-mt-ulap-in-itogon-benguet/"}]'::jsonb, '2026-10-10'),
  ('ulap-11-water-fil', 'ulap', 'water', 'fil',
   'Walang maaasahang natural na water source sa Mt. Ulap Eco-Trail, at wala rin sa mga campsite. Ang tanging tubig sa daan ay ibinebenta sa maliit na tindahan sa Campsite 2 malapit sa summit, na puwedeng sarado o ubos na. Magdala ng hindi bababa sa 2 litro bawat tao mula Ampucao; kaunti lang ang lilim sa mga ridge. Kung may senyales ng dehydration, buksan ang Emergency Guide na Dehydration.',
   'transitpinas.com, thequeensescape.com, lakbaypinas.com',
   '[{"id": "U15", "title": "Mt. Ulap and Gungal Rock (Benguet)", "publisher": "Transit Pinas", "url": "https://transitpinas.com/benguet-mt-ulap-gungal/"}, {"id": "U17", "title": "Mt. Ulap Eco-Trail, Itogon, Benguet travel guide", "publisher": "The Queen''s Escape", "url": "https://thequeensescape.com/mt-ulap-eco-trail-itogon-benguet-2020-travel-guide/"}, {"id": "U19", "title": "Ultimate Guide to Mt. Ulap in Itogon, Benguet", "publisher": "LakbayPinas", "url": "https://lakbaypinas.com/ultimate-guide-to-mt-ulap-in-itogon-benguet/"}]'::jsonb, '2026-10-10'),
  ('ulap-12-closures-and-current-status-en', 'ulap', 'hazards', 'en',
   'The Mt. Ulap Eco-Trail closes often for fires and storms, by order of the Itogon mayor, the Benguet governor or the barangay. In 2026 it closed on 20 April for forest fires and reopened on 1 May; it closed again in late July for Typhoon Kiyapo, reopening days later; and a province-wide suspension of adventure tourism from 5 August, due to a tropical storm and the monsoon, was lifted on 14 September. The Eco-Trail resumed operations on 16 September 2026. Before you travel, check the Itogon municipal website or ask the Itogon tourism office whether the Trail is open, especially in the fire season (February to May) or when a storm is near.',
   'itogon.gov.ph, tribune.net.ph, baguiocityguide.com',
   '[{"id": "U3", "title": "Itogon reopens eco-tourism sites starting May 1st", "publisher": "Municipality of Itogon", "url": "https://itogon.gov.ph/2026/04/itogon-reopens-eco-tourism-sites-starting-may-1st/"}, {"id": "U4", "title": "Tourism, mining activities suspended ahead of Tropical Storm Kiyapo", "publisher": "Municipality of Itogon", "url": "https://itogon.gov.ph/2026/07/tourism-mining-activities-suspended-ahead-of-tropical-storm-kiyapo/"}, {"id": "U6", "title": "Mayor lifts tourism, mining suspension", "publisher": "Municipality of Itogon", "url": "https://itogon.gov.ph/2026/07/mayor-lifts-tourism-mining-suspension/"}, {"id": "U10", "title": "Itogon suspends trekking amid forest fires", "publisher": "Daily Tribune", "url": "https://tribune.net.ph/2026/04/22/itogon-suspends-trekking-amid-forest-fires"}, {"id": "U12", "title": "Mt. Ulap Eco-Trail reopens as Benguet lifts suspension on adventure activities", "publisher": "Baguio City Guide", "url": "https://baguiocityguide.com/mt-ulap-eco-trail-reopens-as-benguet-lifts-suspension-on-adventure-activities/"}]'::jsonb, '2026-10-10'),
  ('ulap-12-closures-and-current-status-fil', 'ulap', 'hazards', 'fil',
   'Madalas isara ang Mt. Ulap Eco-Trail dahil sa sunog at bagyo, sa utos ng mayor ng Itogon, ng gobernador ng Benguet o ng barangay. Noong 2026, isinara ito noong 20 Abril dahil sa forest fire at binuksan noong 1 Mayo; isinara ulit noong huling bahagi ng Hulyo dahil sa Bagyong Kiyapo, at binuksan pagkalipas ng ilang araw; at inalis noong 14 Setyembre ang suspensyon ng adventure tourism sa buong probinsya na nagsimula noong 5 Agosto dahil sa isang tropical storm at habagat. Nagbukas ulit ang Eco-Trail noong 16 Setyembre 2026. Bago bumiyahe, tingnan ang website ng munisipyo ng Itogon o itanong sa Itogon tourism office kung bukas ang Trail, lalo na sa fire season (Pebrero hanggang Mayo) o kapag may paparating na bagyo.',
   'itogon.gov.ph, tribune.net.ph, baguiocityguide.com',
   '[{"id": "U3", "title": "Itogon reopens eco-tourism sites starting May 1st", "publisher": "Municipality of Itogon", "url": "https://itogon.gov.ph/2026/04/itogon-reopens-eco-tourism-sites-starting-may-1st/"}, {"id": "U4", "title": "Tourism, mining activities suspended ahead of Tropical Storm Kiyapo", "publisher": "Municipality of Itogon", "url": "https://itogon.gov.ph/2026/07/tourism-mining-activities-suspended-ahead-of-tropical-storm-kiyapo/"}, {"id": "U6", "title": "Mayor lifts tourism, mining suspension", "publisher": "Municipality of Itogon", "url": "https://itogon.gov.ph/2026/07/mayor-lifts-tourism-mining-suspension/"}, {"id": "U10", "title": "Itogon suspends trekking amid forest fires", "publisher": "Daily Tribune", "url": "https://tribune.net.ph/2026/04/22/itogon-suspends-trekking-amid-forest-fires"}, {"id": "U12", "title": "Mt. Ulap Eco-Trail reopens as Benguet lifts suspension on adventure activities", "publisher": "Baguio City Guide", "url": "https://baguiocityguide.com/mt-ulap-eco-trail-reopens-as-benguet-lifts-suspension-on-adventure-activities/"}]'::jsonb, '2026-10-10'),
  ('ulap-13-fire-rules-smoke-free-en', 'ulap', 'hazards', 'en',
   'Itogon has declared Mt. Ulap smoke-free and vape-free (June 2025) to reduce the risk of grass and forest fires. Forest fires closed the Eco-Trail in April 2026, and police, firefighters, the disaster office and barangay officials enforce the closure orders. Do not smoke or vape anywhere on the Trail. A 2026 blog says open flames are allowed only in designated fire pits at the campsites, with a ₱1,000 fine otherwise and a ₱500 fine for littering; these amounts are not confirmed by the town. Use a stove for cooking and carry out all your trash.',
   'itogon.gov.ph, tribune.net.ph, lakbaypinas.com',
   '[{"id": "U5", "title": "Mt. Ulap smoke- and vape-free declaration", "publisher": "Municipality of Itogon", "url": "https://itogon.gov.ph/?p=4738"}, {"id": "U10", "title": "Itogon suspends trekking amid forest fires", "publisher": "Daily Tribune", "url": "https://tribune.net.ph/2026/04/22/itogon-suspends-trekking-amid-forest-fires"}, {"id": "U19", "title": "Ultimate Guide to Mt. Ulap in Itogon, Benguet", "publisher": "LakbayPinas", "url": "https://lakbaypinas.com/ultimate-guide-to-mt-ulap-in-itogon-benguet/"}]'::jsonb, '2026-10-10'),
  ('ulap-13-fire-rules-smoke-free-fil', 'ulap', 'hazards', 'fil',
   'Idineklara ng Itogon na smoke-free at vape-free ang Mt. Ulap (Hunyo 2025) para mabawasan ang panganib ng sunog sa damuhan at gubat. Isinara ang Eco-Trail noong Abril 2026 dahil sa forest fire, at ang pulis, bumbero, disaster office at mga opisyal ng barangay ang nagpapatupad ng mga utos ng pagsasara. Huwag manigarilyo o mag-vape kahit saan sa Trail. Ayon sa isang 2026 blog, sa mga itinakdang fire pit lang sa campsite puwede ang apoy, may ₱1,000 na multa kapag lumabag, at ₱500 sa pagkakalat; hindi pa ito kinukumpirma ng bayan. Gumamit ng stove sa pagluluto at iuwi ang lahat ng basura.',
   'itogon.gov.ph, tribune.net.ph, lakbaypinas.com',
   '[{"id": "U5", "title": "Mt. Ulap smoke- and vape-free declaration", "publisher": "Municipality of Itogon", "url": "https://itogon.gov.ph/?p=4738"}, {"id": "U10", "title": "Itogon suspends trekking amid forest fires", "publisher": "Daily Tribune", "url": "https://tribune.net.ph/2026/04/22/itogon-suspends-trekking-amid-forest-fires"}, {"id": "U19", "title": "Ultimate Guide to Mt. Ulap in Itogon, Benguet", "publisher": "LakbayPinas", "url": "https://lakbaypinas.com/ultimate-guide-to-mt-ulap-in-itogon-benguet/"}]'::jsonb, '2026-10-10'),
  ('ulap-14-wind-cold-fog-and-lightning-en', 'ulap', 'hazards', 'en',
   'The Mt. Ulap Eco-Trail runs along open ridges with little shade or shelter. Wind can be strong, especially in November, nights at the campsites are cold, and fog can roll in and hide the Trail. No Ulap-specific lightning advice was found, but exposed ridges and peaks are dangerous in thunderstorms (US CDC). Stay with your guide, and get off the open ridge when a storm approaches. If thunder starts, open the Lightning Emergency Guide. If fog hides the Trail and you lose your group, open the Lost on the trail Emergency Guide. If someone gets very cold, open the Hypothermia Emergency Guide.',
   'transitpinas.com, thequeensescape.com, lakbaypinas.com, cdc.gov',
   '[{"id": "U15", "title": "Mt. Ulap and Gungal Rock (Benguet)", "publisher": "Transit Pinas", "url": "https://transitpinas.com/benguet-mt-ulap-gungal/"}, {"id": "U17", "title": "Mt. Ulap Eco-Trail, Itogon, Benguet travel guide", "publisher": "The Queen''s Escape", "url": "https://thequeensescape.com/mt-ulap-eco-trail-itogon-benguet-2020-travel-guide/"}, {"id": "U19", "title": "Ultimate Guide to Mt. Ulap in Itogon, Benguet", "publisher": "LakbayPinas", "url": "https://lakbaypinas.com/ultimate-guide-to-mt-ulap-in-itogon-benguet/"}, {"id": "S10", "title": "Lightning safety", "publisher": "US Centers for Disease Control and Prevention", "url": "https://www.cdc.gov/lightning/safety/index.html"}]'::jsonb, '2026-10-10'),
  ('ulap-14-wind-cold-fog-and-lightning-fil', 'ulap', 'hazards', 'fil',
   'Dumadaan ang Mt. Ulap Eco-Trail sa mga bukas na ridge na halos walang lilim o masisilungan. Puwedeng malakas ang hangin, lalo na tuwing Nobyembre, malamig sa gabi sa mga campsite, at puwedeng biglang bumaba ang fog at matakpan ang Trail. Walang nakitang payo tungkol sa kidlat na para sa Ulap mismo, pero delikado ang mga bukas na ridge at peak kapag may thunderstorm (US CDC). Manatiling kasama ang guide, at umalis sa bukas na ridge kapag may paparating na bagyo. Kapag kumulog, buksan ang Emergency Guide na Lightning. Kung natakpan ng fog ang Trail at nawalay ka sa grupo, buksan ang Emergency Guide na Lost on the trail. Kung may sobrang nilalamig, buksan ang Emergency Guide na Hypothermia.',
   'transitpinas.com, thequeensescape.com, lakbaypinas.com, cdc.gov',
   '[{"id": "U15", "title": "Mt. Ulap and Gungal Rock (Benguet)", "publisher": "Transit Pinas", "url": "https://transitpinas.com/benguet-mt-ulap-gungal/"}, {"id": "U17", "title": "Mt. Ulap Eco-Trail, Itogon, Benguet travel guide", "publisher": "The Queen''s Escape", "url": "https://thequeensescape.com/mt-ulap-eco-trail-itogon-benguet-2020-travel-guide/"}, {"id": "U19", "title": "Ultimate Guide to Mt. Ulap in Itogon, Benguet", "publisher": "LakbayPinas", "url": "https://lakbaypinas.com/ultimate-guide-to-mt-ulap-in-itogon-benguet/"}, {"id": "S10", "title": "Lightning safety", "publisher": "US Centers for Disease Control and Prevention", "url": "https://www.cdc.gov/lightning/safety/index.html"}]'::jsonb, '2026-10-10'),
  ('ulap-15-emergency-contacts-and-hospitals-en', 'ulap', 'hazards', 'en',
   'For an emergency on Mt. Ulap, call 911, the national emergency hotline, and tell your guide at once. The Itogon disaster office (MDRRMO) lists these numbers on the official Itogon website: 0962-967-2977, 0929-862-9895 and 0956-856-3661. Signal is patchy on the Trail and absent at Campsite 2. The nearest hospital is the Itogon district hospital in Tinongdan, about 7 km from Ampucao in a straight line. Baguio General Hospital is about 10 km away and Benguet General Hospital in La Trinidad about 16 km; road distances are longer. There is a police outpost in Itogon Poblacion, about 4 km from Ampucao.',
   'itogon.gov.ph, openstreetmap.org, chanrobles.com, lawphil.net',
   '[{"id": "U2", "title": "Itogon Emergency Hotlines", "publisher": "Municipality of Itogon", "url": "https://itogon.gov.ph/2024/02/itogon-emergency-hotlines/"}, {"id": "U8", "title": "OpenStreetMap data (Mt. Ulap Eco Trail, Waypoints, hospitals)", "publisher": "OpenStreetMap contributors", "url": "https://www.openstreetmap.org/copyright"}, {"id": "U22", "title": "Republic Act No. 6875 (Itogon municipal hospital)", "publisher": "Republic of the Philippines (text via ChanRobles)", "url": "https://www.chanrobles.com/republicacts/republicactno6875.html"}, {"id": "S23", "title": "Executive Order No. 56, s. 2018 (Emergency 911)", "publisher": "Republic of the Philippines (text via LawPhil)", "url": "https://lawphil.net/executive/execord/eo2018/eo_56_2018.html"}]'::jsonb, '2026-10-10'),
  ('ulap-15-emergency-contacts-and-hospitals-fil', 'ulap', 'hazards', 'fil',
   'Para sa emergency sa Mt. Ulap, tumawag sa 911, ang pambansang emergency hotline, at sabihan agad ang guide. Nakalista sa opisyal na website ng Itogon ang mga numero ng disaster office ng bayan (MDRRMO): 0962-967-2977, 0929-862-9895 at 0956-856-3661. Pasulpot-sulpot ang signal sa Trail at wala sa Campsite 2. Ang pinakamalapit na ospital ay ang district hospital ng Itogon sa Tinongdan, mga 7 km mula Ampucao nang tuwiran. Mga 10 km ang Baguio General Hospital at mga 16 km ang Benguet General Hospital sa La Trinidad; mas malayo pa sa kalsada. May police outpost sa Itogon Poblacion, mga 4 km mula Ampucao.',
   'itogon.gov.ph, openstreetmap.org, chanrobles.com, lawphil.net',
   '[{"id": "U2", "title": "Itogon Emergency Hotlines", "publisher": "Municipality of Itogon", "url": "https://itogon.gov.ph/2024/02/itogon-emergency-hotlines/"}, {"id": "U8", "title": "OpenStreetMap data (Mt. Ulap Eco Trail, Waypoints, hospitals)", "publisher": "OpenStreetMap contributors", "url": "https://www.openstreetmap.org/copyright"}, {"id": "U22", "title": "Republic Act No. 6875 (Itogon municipal hospital)", "publisher": "Republic of the Philippines (text via ChanRobles)", "url": "https://www.chanrobles.com/republicacts/republicactno6875.html"}, {"id": "S23", "title": "Executive Order No. 56, s. 2018 (Emergency 911)", "publisher": "Republic of the Philippines (text via LawPhil)", "url": "https://lawphil.net/executive/execord/eo2018/eo_56_2018.html"}]'::jsonb, '2026-10-10'),
  ('ulap-16-mobile-signal-en', 'ulap', 'hazards', 'en',
   'Mobile signal on the Mt. Ulap Eco-Trail is patchy, and hikers report none at Campsite 2 below the summit. Do not count on calling or messaging from every point on the Trail. Download the Mt. Ulap Destination Pack before you leave Baguio or Ampucao: the map, Trail, Waypoints and Guides in Tahak work without signal. Your emergency contacts are recorded on the manifest at the Ampucao Barangay Hall.',
   'transitpinas.com, thequeensescape.com, lakbaypinas.com',
   '[{"id": "U15", "title": "Mt. Ulap and Gungal Rock (Benguet)", "publisher": "Transit Pinas", "url": "https://transitpinas.com/benguet-mt-ulap-gungal/"}, {"id": "U17", "title": "Mt. Ulap Eco-Trail, Itogon, Benguet travel guide", "publisher": "The Queen''s Escape", "url": "https://thequeensescape.com/mt-ulap-eco-trail-itogon-benguet-2020-travel-guide/"}, {"id": "U19", "title": "Ultimate Guide to Mt. Ulap in Itogon, Benguet", "publisher": "LakbayPinas", "url": "https://lakbaypinas.com/ultimate-guide-to-mt-ulap-in-itogon-benguet/"}]'::jsonb, '2026-10-10'),
  ('ulap-16-mobile-signal-fil', 'ulap', 'hazards', 'fil',
   'Pasulpot-sulpot ang signal sa Mt. Ulap Eco-Trail, at ayon sa mga hiker, wala sa Campsite 2 sa ibaba ng summit. Huwag umasang makakatawag o makakapag-text sa bawat bahagi ng Trail. I-download ang Mt. Ulap Destination Pack bago umalis ng Baguio o Ampucao: gumagana nang walang signal ang map, Trail, Waypoints at Guides sa Tahak. Nakatala ang emergency contacts mo sa manifest sa Ampucao Barangay Hall.',
   'transitpinas.com, thequeensescape.com, lakbaypinas.com',
